(function(root){
  'use strict';
  const KEY='mh_toolbox_v1',core=root.toolboxCore,categories=['帮派迷宫','神器攻略','副本攻略'];
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt=n=>Number(n).toLocaleString('zh-CN',{maximumFractionDigits:4});
  const roles=()=>Array.from({length:5},(_,i)=>({name:'角色'+(i+1),target:'',experience:0,balance:0,money:0,contribution:0}));
  const initial=()=>({version:1,entries:JSON.parse(JSON.stringify(root.toolboxGuides)),tables:[],roles:roles()});
  let page,state,view='library',timer=null,ticker=null,windows=[];
  function read(){const data=core.validate(JSON.parse(localStorage.getItem(KEY)||'null')||initial());if(!data.roles)data.roles=roles();return data;}
  function save(next){core.validate(next);localStorage.setItem(KEY,JSON.stringify(next));state=next;}
  function status(text,error=false){const el=page.querySelector('[role=status]');el.textContent=text;el.classList.toggle('tb-error',error);}
  const options=values=>values.map(v=>`<option>${esc(v)}</option>`).join('');
  function minutes(label,value){return `<label>${label}<input name="minutes" type="number" min="1" max="1440" step="1" value="${value}" required></label>`;}
  function total(){const t=state.roles.reduce((a,r)=>{a.exp+=Math.max(0,r.experience-r.balance);a.money+=r.money;a.contribution+=r.contribution;return a;},{exp:0,money:0,contribution:0});return `<div class="tb-results">${[['整组还需经验／点数',fmt(t.exp)],['整组费用',fmt(t.money)+' 万'],['整组帮贡',fmt(t.contribution)]].map(([k,v])=>`<div>${k}<strong>${v}</strong></div>`).join('')}</div>`;}
  function content(){
    if(view==='budget')return `<section><h2>五个角色培养预算</h2><p>按核实后的需求分别填写，已有经验按角色抵扣，费用单位为万梦幻币。一次计划请统一使用经验或修炼点。</p><div data-total>${total()}</div><form data-form="budget"><div class="tb-scroll"><table><thead><tr><th>角色</th><th>培养目标</th><th>需求经验／点数</th><th>已有经验／点数</th><th>费用（万）</th><th>帮贡需求</th></tr></thead><tbody>${state.roles.map((r,i)=>`<tr><td><input name="name${i}" maxlength="100" value="${esc(r.name)}" required></td><td><input name="target${i}" maxlength="200" value="${esc(r.target)}" placeholder="如：修炼 10→15"></td>${['experience','balance','money','contribution'].map(k=>`<td><input type="number" name="${k}${i}" min="0" max="1000000000000" step="${k==='money'?'0.0001':'1'}" value="${r[k]}" required></td>`).join('')}</tr>`).join('')}</tbody></table></div><button>保存并汇总预算</button></form><p>按填写需求汇总，不套用未核实的旧版等级公式；计划费用不会计入实际记账支出。</p></section>`;
    if(view==='library')return `<section><h2>可编辑攻略资料库</h2><p>内置帮派迷宫、轩辕剑之陨开场和乌鸡国的简要资料，可修改、复制或新增。</p><div class="tb-fields"><label>分类<select data-category><option value="">全部攻略</option>${options(categories)}</select></label><label>搜索<input data-search placeholder="标题、内容、来源"></label><button data-action="new">新增攻略</button></div><div data-entries></div></section><section data-editor><h2>新增或编辑攻略</h2><form data-form="entry"><input type="hidden" name="id"><div class="tb-fields"><label>分类<select name="category">${options(categories)}</select></label><label>标题<input name="title" maxlength="150" required></label><label>来源／版本<input name="source" maxlength="1000" placeholder="自写笔记／网址／日期" required></label></div><label>攻略内容<textarea name="text" maxlength="30000" required placeholder="领取条件、准备物品、步骤、战斗要点和实战笔记……"></textarea></label><button>保存攻略</button><button type="reset">清空表单</button></form></section>`;
    if(view==='timer')return `<section><h2>定时提醒</h2><p>切换页面后继续计时；记账本关闭后结束。</p><form data-form="timer" class="tb-fields">${minutes('多少分钟后提醒',30)}<label>提醒内容<input name="message" maxlength="200" value="到时间了，记得检查任务与点卡。" required></label><button>开始提醒</button><button type="button" data-action="cancel-timer">取消提醒</button></form><p data-timer class="tb-timer"></p></section><section><h2>定时关闭游戏</h2><p>选择实际游戏客户端 EXE 后勾选窗口，到时请求正常关闭。游戏若弹出确认框需手动处理；退出记账本会取消定时。</p><button data-action="choose">选择客户端并读取窗口</button><form data-form="close"><div data-windows>${windowList()}</div><div class="tb-fields">${minutes('多少分钟后关闭',60)}<button>设置定时关闭</button><button type="button" data-action="cancel-close">取消关闭定时</button></div></form><p data-close class="tb-timer"></p></section>`;
    return `<section><h2>工具箱备份</h2><p>备份包含攻略、来源和五个角色预算。恢复会替换工具箱数据，操作前会确认。</p><button data-action="export">导出备份</button> <button data-action="import">恢复备份</button><input type="file" accept=".json" data-import hidden></section><section><h2>补充内置攻略</h2><p>添加缺失的内置条目，保留你已经修改的攻略。</p><button data-action="seed">补充缺失的内置攻略</button></section>`;
  }
  function windowList(){return windows.length?windows.map(w=>`<label><span><input type="checkbox" name="pid" value="${w.pid}"> ${esc(w.title)}（PID ${w.pid}）</span></label>`).join(''):'<p>尚未选择客户端，或没有找到该客户端的运行窗口。</p>';}
  function render(){page.innerHTML=`<header><div><h1>实用工具箱</h1><p>五开培养预算 · 可编辑攻略 · 游戏定时</p></div><button data-action="back">返回五开记账</button></header><nav>${[['library','攻略资料库'],['budget','五开培养预算'],['timer','提醒与关闭游戏'],['backup','资料备份']].map(([id,label])=>`<button data-view="${id}" aria-pressed="${view===id}">${label}</button>`).join('')}</nav><div role="status" aria-live="polite" class="tb-status"></div><main>${content()}</main>`;page.scrollTop=0;if(view==='library')entries();tick();if(view==='timer')poll();}
  function entries(){const q=page.querySelector('[data-search]').value.trim(),cat=page.querySelector('[data-category]').value;page.querySelector('[data-entries]').innerHTML=state.entries.filter(e=>(!cat||e.category===cat)&&(!q||(e.title+' '+e.text+' '+e.source).includes(q))).map(e=>`<details><summary>${esc(e.category)} · ${esc(e.title)}</summary><p class="tb-text">${esc(e.text)}</p><p class="tb-source">来源／版本：${esc(e.source)}</p><button data-edit="${esc(e.id)}">编辑</button> <button data-copy="${esc(e.id)}">复制为新攻略</button> <button data-remove="${esc(e.id)}">删除</button></details>`).join('')||'<p>没有匹配攻略，可以新增或导入备份。</p>';}
  function edit(entry,copy=false){const f=page.querySelector('[data-form=entry]');f.reset();f.elements.id.value='';if(entry){['id','title','text','source','category'].forEach(k=>f.elements[k].value=entry[k]);if(copy){f.elements.id.value='';f.elements.title.value=entry.title+'（副本）';}}page.querySelector('[data-editor]').scrollIntoView({block:'center'});f.elements.title.focus();}
  function tick(){const el=page?.querySelector('[data-timer]');if(el)el.textContent=timer?timer.message+' · 剩余 '+Math.max(0,Math.ceil((timer.end-Date.now())/1000))+' 秒':'尚未设置提醒';if(timer&&Date.now()>=timer.end){const msg=timer.message;cancel();alert('工具箱提醒：'+msg);}}
  function cancel(){timer=null;if(ticker)clearInterval(ticker);ticker=null;tick();}
  async function poll(){try{if(!root.electronAPI?.gameCloseStatus)return;const s=await root.electronAPI.gameCloseStatus(),el=page?.querySelector('[data-close]');if(el)el.textContent=s.message+(s.active?' · 剩余 '+Math.max(0,Math.ceil((s.end-Date.now())/60000))+' 分钟':'');}catch(err){const el=page?.querySelector('[data-close]');if(el)el.textContent=err.message;}}
  function download(){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='小宝贝工具箱备份.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function bind(){
    page.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
      if(b.dataset.view){view=b.dataset.view;render();return;}
      if(b.dataset.edit||b.dataset.copy){edit(state.entries.find(x=>x.id===(b.dataset.edit||b.dataset.copy)),!!b.dataset.copy);return;}
      if(b.dataset.remove){if(confirm('删除这篇攻略？')){save({...state,entries:state.entries.filter(x=>x.id!==b.dataset.remove)});entries();}return;}
      const a=b.dataset.action;
      if(a==='new')edit();if(a==='back'){hide();document.getElementById('app').hidden=false;root.projectNavigation?.select('accounting');}
      if(a==='export')download();if(a==='import')page.querySelector('[data-import]').click();if(a==='cancel-timer')cancel();
      if(a==='seed'){const next=JSON.parse(JSON.stringify(state));root.toolboxGuides.forEach(g=>{if(!next.entries.some(e=>e.id===g.id))next.entries.push({...g});});save(next);status('缺失攻略已补充，已有修改保留');}
      if(a==='choose'){if(!root.electronAPI?.chooseGameWindows)throw new Error('请在桌面版使用');b.disabled=true;const r=await root.electronAPI.chooseGameWindows();if(!r.canceled){windows=r.windows;page.querySelector('[data-windows]').innerHTML=windowList();status('已读取 '+windows.length+' 个窗口');}}
      if(a==='cancel-close'){if(!root.electronAPI?.cancelGameClose)throw new Error('请在桌面版使用');await root.electronAPI.cancelGameClose();poll();}
    }catch(err){status(err.message,true);}finally{b.disabled=false;}});
    page.addEventListener('input',e=>{if(e.target.matches('[data-search]'))entries();});
    page.addEventListener('change',async e=>{if(e.target.matches('[data-category]'))entries();if(e.target.matches('[data-import]')&&e.target.files[0]){try{const file=e.target.files[0];if(file.size>5*1024*1024)throw new Error('备份不能超过 5 MB');const next=core.validate(JSON.parse((await file.text()).replace(/^\uFEFF/,'')));if(!next.roles)next.roles=roles();if(!confirm('用备份替换当前攻略和培养预算？'))return;save(next);render();status('备份已恢复');}catch(err){status('未恢复：'+err.message,true);}finally{e.target.value='';}}});
    page.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));try{
      if(f.dataset.form==='budget'){const next=JSON.parse(JSON.stringify(state));next.roles=Array.from({length:5},(_,i)=>({name:d['name'+i].trim(),target:d['target'+i].trim(),experience:core.number(d['experience'+i],'经验需求',1e12,true),balance:core.number(d['balance'+i],'已有经验',1e12,true),money:core.number(d['money'+i],'费用'),contribution:core.number(d['contribution'+i],'帮贡',1e12,true)}));save(next);page.querySelector('[data-total]').innerHTML=total();status('角色预算已保存');}
      if(f.dataset.form==='entry'){const entry={id:d.id||'entry-'+Date.now()+'-'+Math.random().toString(36).slice(2),title:d.title.trim(),category:d.category,text:d.text.trim(),source:d.source.trim()},next=JSON.parse(JSON.stringify(state)),i=next.entries.findIndex(x=>x.id===entry.id);if(i<0)next.entries.push(entry);else next.entries[i]=entry;save(next);f.reset();f.elements.id.value='';entries();status('攻略已保存');}
      if(f.dataset.form==='timer'){const n=core.number(d.minutes,'提醒分钟',1440,true);if(!n)throw new Error('至少 1 分钟');cancel();timer={end:Date.now()+n*60000,message:d.message};ticker=setInterval(tick,1000);tick();status('提醒已开始');}
      if(f.dataset.form==='close'){if(!root.electronAPI?.scheduleGameClose)throw new Error('请在桌面版使用');const pids=Array.from(f.querySelectorAll('[name=pid]:checked')).map(x=>Number(x.value));if(!pids.length)throw new Error('请先勾选目标窗口');const n=core.number(d.minutes,'关闭分钟',1440,true);if(!n)throw new Error('至少 1 分钟');const r=await root.electronAPI.scheduleGameClose({pids,minutes:n});status(r.canceled?'已取消':'定时关闭已设置');poll();}
    }catch(err){status(err.message,true);}});
  }
  function open(){root.treasureProject?.hide();try{state=read();}catch(err){alert('工具箱读取失败：'+err.message);return;}if(!page){page=document.createElement('section');page.id='toolbox-project';page.setAttribute('aria-label','实用工具箱');document.body.append(page);bind();setInterval(()=>{if(!page.hidden&&view==='timer')poll();},5000);}root.ringProject?.hide();root.sceneProject?.hide();root.supportProject?.hide();document.getElementById('app').hidden=true;page.hidden=false;root.projectNavigation?.select('toolbox');render();}
  function hide(){if(page)page.hidden=true;}
  root.toolboxProject={open,hide};
})(window);
